/**
 * Return one page of the read actions a Bot holds that can be a memory source for the caller: actions that only read and change nothing. The caller must be able to use the Bot. A missing cursor starts at the first page and nextCursor null ends the list.
 * @summary List what a Bot could read facts in from
 */

export const listMemorySourceToolsPathBotIdRegExp = new RegExp("\\S");

export const ListMemorySourceToolsParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization. Until multi-organization lands every install has one, addressed as `default`.",
    ),
  botId: zod
    .string()
    .min(1)
    .regex(listMemorySourceToolsPathBotIdRegExp)
    .describe("The Bot's id."),
});

export const listMemorySourceToolsQueryLimitDefault = 50;
export const listMemorySourceToolsQueryLimitMax = 100;

export const listMemorySourceToolsQueryCursorMax = 4096;

export const listMemorySourceToolsQueryCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListMemorySourceToolsQueryParams = zod.object({
  limit: zod
    .int()
    .min(1)
    .max(listMemorySourceToolsQueryLimitMax)
    .default(listMemorySourceToolsQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listMemorySourceToolsQueryCursorMax)
    .regex(listMemorySourceToolsQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

export const listMemorySourceToolsResponseNextCursorMax = 4096;

export const listMemorySourceToolsResponseNextCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListMemorySourceToolsResponse = zod.object({
  tools: zod.array(
    zod.object({
      ref: zod.string().describe("The action, as appId/toolName."),
      title: zod.string(),
      description: zod.string(),
      inputSchema: zod
        .record(zod.string(), zod.unknown())
        .describe("The JSON Schema of what the action is called with."),
    }),
  ),
  nextCursor: zod
    .string()
    .max(listMemorySourceToolsResponseNextCursorMax)
    .regex(listMemorySourceToolsResponseNextCursorRegExp)
    .nullable()
    .describe(
      "Pass as cursor for the next page. Null ends the list. Written in URL-safe base64, the only form the cursor parameter accepts.",
    ),
});
